<script setup lang="ts">
import {ref,onMounted} from 'vue';
import type {DistributionGrant,Page} from '@survey/shared';
import {api} from '../api';
import {queryPage} from '../library-client';
const props=defineProps<{questionId:string;revision:number;versionId:string;disabled?:boolean}>(),emit=defineEmits<{changed:[]}>(),rows=ref<DistributionGrant[]>([]),cursor=ref<string|null>(null),username=ref(''),busy=ref(false),error=ref(''),notice=ref('');
async function load(more=false){busy.value=true;error.value='';try{const p=await api<Page<DistributionGrant>>(`/questions/${props.questionId}/distribution-grants`+queryPage({limit:'20',cursor:more?cursor.value??undefined:undefined}));rows.value=more?[...rows.value,...p.items]:p.items;cursor.value=p.nextCursor;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function change(g:DistributionGrant|null,revoke=false){if(props.disabled||busy.value)return;busy.value=true;error.value='';notice.value='';try{await api(`/questions/${props.questionId}/distribution-grants${revoke?`/${g!.id}/revocation`:''}`,revoke?'POST':'PUT',{expectedRevision:props.revision,expectedGrantRevision:g?.revision??null,...(revoke?{}:{questionVersionId:props.versionId,username:g?.publisherUsername??username.value})});emit('changed');await load();notice.value=revoke?'公开授权已撤销，未来选用立即停止；已经生成的问卷继续保留。':'已授予该正式版本的公开分发权；其他版本和上游作者的权利需分别取得。';}catch(e){error.value=(e as Error).message;emit('changed');}finally{busy.value=false;}}
onMounted(()=>load());
</script>
<template><section class="panel"><h2>具体版本公开分发授权</h2><p class="muted">授权当前选中的正式版本给指定模板发布者，可让其在广场公开该结构。这与私人共享不同，不包含未来版本，也不能代替上游作者授权。</p><p v-if="error" class="error" role="alert">{{error}} <button class="quiet" @click="load()">刷新公开授权</button></p><p v-if="notice" class="saved" role="status">{{notice}}</p><form @submit.prevent="change(rows.find(g=>g.questionVersionId===versionId&&g.publisherUsername.toLowerCase()===username.trim().toLowerCase())??null)"><label for="distribution-publisher">模板发布者用户名</label><input id="distribution-publisher" v-model="username" :disabled="busy||disabled" autocomplete="off"><button class="secondary" :disabled="busy||disabled||!username.trim()||!versionId">授予所选版本公开权</button></form><p v-if="!rows.length&&!busy">尚无公开分发授权。</p><ul class="library-rows"><li v-for="g in rows" :key="g.id"><span>{{g.publisherUsername}} · {{g.questionVersionId===versionId?'当前所选正式版':'其他正式版'}} · {{g.state==='active'?'公开授权有效':'已撤销'}}</span><button class="quiet" :disabled="busy||disabled||g.questionVersionId!==versionId" @click="change(g,g.state==='active')">{{g.state==='active'?'撤销公开授权':'重新授予公开权'}}</button></li></ul><button v-if="cursor" class="secondary" :disabled="busy||disabled" @click="load(true)">更多公开授权</button></section></template>
